import {stages,layerNames,locations,createProject,dimensions,pieces,change,confirm,canApply,start,cancel,fail,finish,restore,undoLayer,addStroke,undoStroke,acceptTrees,visibleStrokePoints,canExport,statusText} from './state.js';
const $=id=>document.getElementById(id),layerLabels={terrain:'Terreny',vegetation:'Vegetació',transport:'Vies',buildings:'Edificis'};
let project=createProject(),timer=null,gesture=null,materials=4;
const palettes={1:['#c6b38d','#c6b38d','#c6b38d','#c6b38d'],2:['#c6b38d','#8dc5ca','#c6b38d','#c6b38d'],4:['#c6b38d','#8dc5ca','#eee9dc','#4e8966'],8:['#c6b38d','#8dc5ca','#eee9dc','#5d855f']};
const choices=(values,value)=>values.map(([key,label])=>`<option value="${key}"${String(key)===String(value)?' selected':''}>${label}</option>`).join('');
const select=(key,label,values)=>`<label for="set-${key}">${label}</label><select id="set-${key}" data-setting="${key}">${choices(values,project.settings[key])}</select>`;
const check=(key,label)=>`<label class="check-row"><input type="checkbox" data-setting="${key}"${project.settings[key]?' checked':''}><span>${label}</span></label>`;
const sceneDirty=()=>layerNames.some(id=>project.layers[id].hasResult&&!['ready','omitted','review'].includes(project.layers[id].status));
function controls(){
 const s=project.settings,id=layerNames[project.step-2];
 let content='';
 if(project.step===0){const [cols,rows]=pieces(project);content=select('size','Mida del projecte', [['150x150','15 × 15 cm'],['180x180','18 × 18 cm'],['200x200','20 × 20 cm'],['150x200','15 × 20 cm'],['200x150','20 × 15 cm'],['300x300','30 × 30 cm'],['400x400','40 × 40 cm']])+select('plate','Mida útil de cada peça',[['150','15 × 15 cm'],['180','18 × 18 cm'],['200','20 × 20 cm'],['250','25 × 25 cm']])+`<p class="model-info">${cols*rows===1?'Una sola peça.':`${cols*rows} peces · ${cols} columnes × ${rows} files.`}</p><p class="hint">Aquesta mida defineix el retall quan triïs el territori.</p>`;}
 if(project.step===1){content=select('location','Territori de prova',Object.entries(locations).map(([key,p])=>[key,`${p.name} (${p.region})`]))+select('rotation','Orientació del retall',[[0,'Nord a dalt'],[25,'Gir de 25°'],[90,'Gir de 90°']])+`<p class="hint">Dos exemples per revisar el recorregut. Al producte, aquesta etapa tindria cerca i mapa amb el retall de la mida escollida.</p><div class="note-line">${project.strokes.length?`${project.strokes.length} traços desats. Els de l’altre territori es conservaran ocults.`:'El canvi de lloc no esborra els traços anteriors.'}</div>`;}
 if(project.step===2)content=select('exaggeration','Exageració del relleu',[[1,'×1'],[1.5,'×1,5'],[2,'×2'],[3,'×3']])+select('detail','Detall', [['rapid','Ràpid'],['equilibrat','Equilibrat'],['alt','Alt']])+`<p class="hint">El terreny inclou aigua, terra i cobertura verda. Els arbres amb volum s’afegeixen a l’etapa següent.</p><div class="note-line">Font prevista: relleu disponible per a la zona. Cotes originals i estimacions identificades.</div>`;
 if(project.step===3)content=check('trees','Afegir arbres amb volum')+select('treeType','Forma dels arbres',[['mixed','Variació natural'],['round','Arrodonida'],['tall','Allargada']])+`<div class="brush-tools" role="group" aria-label="Eines de vegetació">${[['navigate','↖ Navega'],['add','＋ Pinzell'],['erase','− Goma']].map(([tool,label])=>`<button data-tool="${tool}" aria-pressed="${project.tool===tool}"${!project.scene.layers.vegetation||project.layers.terrain.status!=='ready'?' disabled':''}>${label}</button>`).join('')}</div><label for="brush-density">Densitat del pinzell <span class="control-value">×${project.density.toLocaleString('ca')}</span></label><input id="brush-density" type="range" min=".25" max="2" step=".25" value="${project.density}"><p class="hint">Pots pintar sobre la vista il·lustrativa. La densitat afecta els traços nous.</p><button class="quiet-button" data-action="undo-stroke"${!project.strokes.length?' disabled':''}>↶ Desfer últim traç</button>${project.layers.vegetation.status==='review'?`<div class="note-line">${project.conflicts} arbres ocults per vies o edificis. Els traços continuen desats.</div><button class="secondary" data-action="accept-trees">Acceptar els ajustos dels arbres</button>`:'<div class="note-line">Quan afegeixis vies o edificis, podràs revisar els arbres que hi coincideixin.</div>'}`;
 if(project.step===4)content=select('roadRise','Relleu dels camins',[[0,'Arran de terreny'],[.5,'Realç de 0,5 mm'],[1,'Realç d’1 mm']])+select('railRise','Relleu de ferrocarrils',[[0,'Igual que els camins'],[.5,'+0,5 mm sobre els camins'],[1,'+1 mm sobre els camins']])+check('tunnels','Túnels estimats · experimental')+'<p class="hint">Carreteres, ferrocarrils, ponts i túnels formen una mateixa capa. Les estimacions es diferencien de les cotes acreditades.</p><div class="note-line">Els arbres que hi coincideixin s’ocultaran. Cap traç del pinzell s’esborrarà.</div>';
 if(project.step===5)content=select('source','Font dels edificis',[['icgc','ICGC'],['osm','OpenStreetMap'],['catastre','Catastre · parts']])+select('height','Altura màxima',[[3,'3 metres reals'],[5,'5 metres reals'],[10,'10 metres reals'],[20,'20 metres reals']])+'<p class="hint">La font disponible dependrà de la zona. Les cobertes i altures reals requereixen dades que les descriguin.</p><div class="note-line">Canviar la font també pot ajustar arbres i suports de ponts, conservant el terreny.</div>';
 const prerequisite=project.step>=2&&!canApply(project,id)&&!project.job?'<p class="hint">'+(!project.accepted.piece?'Confirma primer la mida del projecte.':!project.accepted.place?'Confirma primer el territori.':'Prepara primer el terreny.')+'</p>':'';
 return `<h2 id="panel-title">${stages[project.step]}</h2>${prerequisite}<fieldset class="stage-fields"${project.job?' disabled':''}>${content}</fieldset>${id&&id!=='terrain'?'<button class="quiet-button" data-action="omit"'+(!canApply(project,id)?' disabled':'')+'>Continuar sense aquesta capa</button>':''}`;
}
function render(){
 $('step-counter').textContent=`Pas ${project.step+1} de ${stages.length}`;
 $('stage-nav').innerHTML=stages.map((name,i)=>{const text=i===0?project.accepted.piece?'Confirmada':'Pendent':i===1?project.accepted.place?'Confirmat':'Pendent':statusText[project.layers[layerNames[i-2]].status];return `<button class="stage-button" data-step="${i}"${project.step===i?' aria-current="step"':''}${project.job?' disabled':''}><span class="stage-number">${String(i+1).padStart(2,'0')}</span><span>${name}</span><span class="stage-status">${text}</span></button>`;}).join('');
 $('controls').innerHTML=controls();const currentId=layerNames[project.step-2];
 $('apply').textContent=project.step===0?'Confirmar mida':project.step===1?'Confirmar territori':project.layers[currentId].status==='error'?'Tornar-ho a provar':`Aplicar ${stages[project.step].toLowerCase()}`;
 $('apply').disabled=!!project.job||project.step>=2&&!canApply(project,currentId);
 $('back').disabled=!!project.job||project.step===0;$('next').disabled=!!project.job||project.step===5||(project.step===0?!project.accepted.piece:project.step===1?!project.accepted.place:!['ready','omitted','review'].includes(project.layers[currentId].status));
 $('next').textContent=project.step<5?`${stages[project.step+1]} →`:'Final';
 const [w,h]=dimensions(project),[cols,rows]=pieces(project);$('model-size').textContent=`${w} × ${h}`;$('piece-count').textContent=String(cols*rows);$('piece-label').textContent=cols*rows===1?'Peça':`Peces · ${cols} × ${rows}`;
 $('project-place').textContent=project.accepted.place?locations[project.settings.location].name:'Territori pendent de confirmar';$('pending-size').hidden=!sceneDirty();$('pending-size').textContent='La vista conserva el resultat anterior fins a aplicar els canvis.';
 $('layer-status').innerHTML=layerNames.map(id=>`<li data-state="${project.layers[id].status}"><span>${layerLabels[id]}</span><span>${statusText[project.layers[id].status]}</span></li>`).join('');
 $('restore-settings').hidden=!project.changes.length&&!layerNames.some(id=>project.layers[id].status==='error');$('restore-settings').disabled=!!project.job;
 const outside=project.strokes.filter(t=>t.location!==project.scene.location).length;$('brush-review').hidden=!project.strokes.length;$('stroke-summary').textContent=`${project.strokes.length} ${project.strokes.length===1?'traç conservat':'traços conservats'}${outside?` · ${outside} fora del territori visible`:''}.`;$('conflict-summary').textContent=project.conflicts?`${project.conflicts} arbres ocults per obstacles. Els traços no s’han perdut.`:'Cap arbre manual ocult per obstacles.';
 $('review-trees').textContent=project.layers.vegetation.status==='review'?'Revisar els arbres afectats':'Anar a la vegetació';$('review-trees').disabled=!!project.job;$('undo-layer').hidden=!project.undo;$('undo-layer').disabled=!!project.job||project.changes.length>0;
 $('review-export').disabled=!canExport(project);$('export-reason').textContent=canExport(project)?'Capes coherents. Pots revisar mides, materials i omissions.':project.layers.vegetation.status==='review'?'Revisa els arbres afectats abans de continuar.':layerNames.some(id=>project.layers[id].status==='error')?'Resol l’error o recupera els ajustos anteriors.':'Prepara o omet les capes pendents abans de continuar.';
 $('demo-stroke').disabled=!!project.job||!project.scene.layers.vegetation||project.layers.terrain.status!=='ready';$('demo-error').disabled=!!project.job||project.step<2||!canApply(project,currentId);$('reset-demo').disabled=!!project.job;
 $('working').hidden=!project.job;$('landscape').setAttribute('aria-busy',String(!!project.job));$('notice').textContent=project.notice;$('notice').classList.toggle('error',layerNames.some(id=>project.layers[id].status==='error'));
 $('top-view').setAttribute('aria-pressed',String(project.view==='top'));$('scene-caption').textContent=project.scene.layers.terrain?`${locations[project.scene.location].name} · paisatge esquemàtic${sceneDirty()?' · vista anterior':''}`:'Paisatge esquemàtic · prepara el terreny per incorporar capes.';
 const colors=palettes[materials];$('legend').innerHTML=['Terreny','Aigua','Construccions','Vegetació'].map((name,i)=>`<span><i style="--swatch:${colors[i]}"></i>${name}</span>`).join('');drawScene();
}
function drawScene(){
 const colors=palettes[materials],shown=project.scene.layers,[mmW,mmH]=project.scene.size.split('x').map(Number);let w=580,h=w*mmH/mmW;if(h>460){w*=460/h;h=460;}
 const view=project.view==='top'?'rotate(0) scale(1 1)':'rotate(-25) scale(1 .62)',transform=`translate(450 340) ${view} translate(${-w/2} ${-h/2})`;
 const p=(x,y)=>`${x*w},${y*h}`,road=`M ${p(.02,.21)} C ${p(.3,.37)} ${p(.5,.48)} ${p(.98,.79)}`,tree=(x,y,r=7)=>{const stretch=project.scene.treeType==='round'?1:project.scene.treeType==='tall'?1.65:.9+((x*31+y*17)%1)*.55;return `<ellipse cx="${x*w}" cy="${y*h}" rx="${r}" ry="${r*stretch}" fill="${colors[3]}" stroke="#647459" stroke-width=".8"/>`;};
 let seed=74;const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/2**32;};let trees='';
 if(shown.vegetation&&project.scene.trees)for(let i=0;i<86;i++){const x=.06+rand()*.88,y=.07+rand()*.86;if(project.scene.location==='tamariu'&&x<.27&&y>.5)continue;if(shown.transport&&Math.abs(y-(.2+.6*x))<.075||shown.buildings&&x>.55&&x<.84&&y>.34&&y<.7)continue;trees+=tree(x,y,4+rand()*4);}
 if(shown.vegetation)for(const point of visibleStrokePoints(project).filter(t=>!t.hidden&&!t.erased))trees+=tree(point.x,point.y,8);
 const contours=Array.from({length:7},(_,i)=>`<path d="M ${p(.04,.08+i*.12)} Q ${p(.3,.3+i*.05)} ${p(.5,.14+i*.1)} T ${p(.97,.12+i*.12)}" fill="none" stroke="#ac9b75" stroke-width="1.2" opacity=".65"/>`).join('');
 const water=project.scene.location==='tamariu'?`<path d="M 0 ${h*.44} Q ${w*.4} ${h*.5} ${w*.28} ${h} H 0 Z" fill="${colors[1]}"/>`:'';
 const built=shown.buildings?[[.61,.4,.1,.1],[.73,.49,.065,.12],[.59,.58,.08,.08],[.79,.36,.07,.08]].map(([x,y,bw,bh])=>`<rect x="${x*w}" y="${y*h}" width="${bw*w}" height="${bh*h}" fill="${colors[2]}" stroke="#9d9a87" stroke-width="1.3"/>`).join(''):'';
 $('scene').innerHTML=`<g id="model-surface" transform="${transform}"><path d="M 0 0 H ${w} V ${h+26} H 0 Z" fill="#b4a17c" stroke="#9c8b6c" stroke-width="1"/><rect width="${w}" height="${h}" fill="${shown.terrain?colors[0]:'#e4e9dc'}" stroke="#a5b69b" stroke-width="1.3"/>${shown.terrain?`<path d="M ${p(0,0)} H ${w} V ${h*.65} Q ${w*.68} ${h*.89} ${w*.42} ${h*.54} T 0 ${h*.7} Z" fill="${colors[3]}" opacity=".35"/>${contours}${water}`:''}${shown.transport?`<path d="${road}" fill="none" stroke="#a79d81" stroke-width="${Math.max(12,w*.032)}"/><path d="${road}" fill="none" stroke="${colors[2]}" stroke-width="${Math.max(9,w*.025)}"/><path d="M ${p(.12,.95)} Q ${p(.45,.5)} ${p(.91,.03)}" fill="none" stroke="${materials===8?'#6f7476':colors[2]}" stroke-width="5"/>`:''}${trees}${built}${shown.terrain?'':`<text x="${w/2}" y="${h/2}" fill="#7e8b75" text-anchor="middle" font-size="16">El terreny apareixerà aquí</text>`}</g>`;
 $('landscape').classList.toggle('painting',project.step===3&&project.tool!=='navigate'&&shown.vegetation&&!project.job);
}
function go(step){if(project.job)return;project.step=Math.max(0,Math.min(5,step));project.tool='navigate';render();$('controls').scrollTop=0;}
function applyLayer(omit=false,withError=false){const id=layerNames[project.step-2];if(!start(project,id))return;project.tool='navigate';render();timer=setTimeout(()=>{timer=null;if(withError)fail(project);else finish(project,{omit:omit||id==='vegetation'&&!project.settings.trees});render();},450);}
function action(name){if(name==='omit')applyLayer(true);if(name==='undo-stroke'){undoStroke(project);render();}if(name==='accept-trees'){acceptTrees(project);render();}}
$('stage-nav').addEventListener('click',e=>{const button=e.target.closest('[data-step]');if(button)go(Number(button.dataset.step));});
$('controls').addEventListener('change',e=>{if(e.target.dataset.setting){let value=e.target.type==='checkbox'?e.target.checked:e.target.value;if(['plate','rotation','exaggeration','roadRise','railRise','height'].includes(e.target.dataset.setting))value=Number(value);change(project,e.target.dataset.setting,value);render();}if(e.target.id==='brush-density'){project.density=Number(e.target.value);render();}});
$('controls').addEventListener('click',e=>{const button=e.target.closest('button');if(!button)return;if(button.dataset.tool){project.tool=button.dataset.tool;render();}if(button.dataset.action)action(button.dataset.action);});
$('apply').onclick=()=>{if(project.step<2){confirm(project,project.step===0?'piece':'place');render();}else applyLayer();};$('back').onclick=()=>go(project.step-1);$('next').onclick=()=>go(project.step+1);
$('cancel-job').onclick=()=>{clearTimeout(timer);timer=null;cancel(project);render();};$('restore-settings').onclick=()=>{restore(project);render();};$('review-trees').onclick=()=>go(3);$('undo-layer').onclick=()=>{undoLayer(project);render();};
$('materials').onchange=e=>{materials=Number(e.target.value);render();};$('top-view').onclick=()=>{project.view=project.view==='top'?'perspective':'top';render();};$('reset-view').onclick=()=>{project.view='perspective';render();};
$('demo-stroke').onclick=()=>{addStroke(project,[{x:.36,y:.42},{x:.42,y:.45},{x:.47,y:.48}]);render();};$('demo-error').onclick=()=>applyLayer(false,true);$('reset-demo').onclick=()=>{project=createProject();materials=4;$('materials').value='4';render();};
$('about').onclick=()=>$('about-dialog').showModal();for(const button of document.querySelectorAll('[data-close]'))button.onclick=()=>button.closest('dialog').close();
$('review-export').onclick=()=>{if(!canExport(project))return;const [w,h]=dimensions(project),[cols,rows]=pieces(project);$('export-summary').textContent=`${locations[project.settings.location].name} · ${w} × ${h} mm · ${cols*rows} ${cols*rows===1?'peça':'peces'} · ${materials} ${materials===1?'material':'materials'}.`;$('export-layers').innerHTML=layerNames.map(id=>`<li>${layerLabels[id]}: ${statusText[project.layers[id].status].toLowerCase()}.</li>`).join('');$('export-dialog').showModal();};
function pointAt(e){const surface=$('model-surface'),matrix=surface?.getScreenCTM();if(!matrix)return null;const p=new DOMPoint(e.clientX,e.clientY).matrixTransform(matrix.inverse()),rect=surface.querySelector('rect');if(!rect)return null;const x=p.x/Number(rect.getAttribute('width')),y=p.y/Number(rect.getAttribute('height'));return x>.03&&x<.97&&y>.03&&y<.97?{x,y}:null;}
$('landscape').addEventListener('pointerdown',e=>{if(e.button!==0||project.step!==3||project.tool==='navigate'||project.job||!project.scene.layers.vegetation)return;const point=pointAt(e);if(!point)return;gesture={mode:project.tool,points:[point]};e.currentTarget.setPointerCapture(e.pointerId);e.preventDefault();});
$('landscape').addEventListener('pointermove',e=>{if(!gesture)return;const point=pointAt(e),last=gesture.points.at(-1);if(point&&Math.hypot(point.x-last.x,point.y-last.y)>.035)gesture.points.push(point);});
function finishStroke(){if(!gesture)return;let points=gesture.points;if(gesture.mode==='add'){
 const stride=project.density<.5?2:1,copies=Math.max(1,Math.round(project.density*2));points=points.filter((_,i)=>i%stride===0).flatMap(p=>Array.from({length:copies},(_,i)=>{const a=i*2.3999632297;return {x:Math.min(.97,Math.max(.03,p.x+(i?Math.cos(a)*.023:0))),y:Math.min(.97,Math.max(.03,p.y+(i?Math.sin(a)*.023:0)))};}));
 }addStroke(project,points,gesture.mode);gesture=null;render();}
$('landscape').addEventListener('pointerup',finishStroke);$('landscape').addEventListener('pointercancel',()=>{gesture=null;});
render();
